def get_geonode_rotating_proxy():
    """Generate Geonode rotating residential proxy config"""
    return {
        "type": "socks5",
        "host": GEONODE_HOST,
        "port": GEONODE_PORT,
        "username": GEONODE_USERNAME,
        "password": GEONODE_PASSWORD
    }

def is_results_page(url):
    return ("/transport/flights/" in url and "/config/" not in url and "captcha" not in url.lower())

def is_details_page(url):
    return ("/transport/flights/" in url and "/config/" in url and "captcha" not in url.lower())

def generate_random_flight_url():
    """Generate random Skyscanner flight search URL"""
    airports = list(AIRPORT_CODES.keys())
    origin = random.choice(airports)
    destination = random.choice([a for a in airports if a != origin])
    
    days_ahead = random.randint(7, 90)
    flight_date = datetime.datetime.now() + datetime.timedelta(days=days_ahead)
    date_str = flight_date.strftime("%y%m%d")
    
    adults = random.randint(1, 4)
    cabin_class = random.choice(["economy", "premium_economy", "business", "first"])
    one_way = random.choice([True, False])
    rtn = 0 if one_way else 1
    
    flight_url = (
        f"https://www.skyscanner.co.in/transport/flights/"
        f"{origin.lower()}/{destination.lower()}/{date_str}/"
        f"?adultsv2={adults}"
        f"&cabinclass={cabin_class}"
        f"&childrenv2="
        f"&ref=home"
        f"&rtn={rtn}"
        f"&outboundaltsenabled=false"
        f"&inboundaltsenabled=false"
        f"&preferdirects=false"
    )
    
    logging.info(f"\nGenerated Flight Search:")
    logging.info(f"   Route: {AIRPORT_CODES[origin]} -> {AIRPORT_CODES[destination]}")
    logging.info(f"   Date: {flight_date.strftime('%d %b %Y')}")
    logging.info(f"   Adults: {adults}, Class: {cabin_class}, {'One-way' if one_way else 'Round-trip'}")
    
    return flight_url

def handle_captcha_challenge(page: Page, max_retries=3):
    """Handle CAPTCHA with press & hold"""
    for attempt in range(max_retries):
        try:
            logging.info(f"\n   CAPTCHA Handler - Attempt {attempt + 1}/{max_retries}")
            
            current_url = page.url
            if "captcha" not in current_url.lower():
                logging.info("   No captcha detected in URL")
                return False
            
            page.wait_for_load_state("load", timeout=30000)
            time.sleep(3)
            
            button_found = False
            target_frame = page
            button_element = None
            
            # Try main page first
            try:
                button_element = page.locator("text=/PRESS.*HOLD/i").first
                if button_element.is_visible(timeout=5000):
                    button_found = True
                    logging.info("   Button found in main page")
            except:
                pass
            
            # Try frames if not found
            if not button_found:
                frames = page.frames
                for idx, frame in enumerate(frames):
                    try:
                        button_element = frame.locator("text=/PRESS.*HOLD/i").first
                        if button_element.is_visible(timeout=5000):
                            target_frame = frame
                            button_found = True
                            logging.info(f"   Button found in frame {idx}")
                            break
                    except:
                        continue
            
            if not button_found:
                logging.warning("   CAPTCHA button not found")
                if attempt < max_retries - 1:
                    time.sleep(5)
                continue
            
            # Get button position
            bounding_box = button_element.bounding_box()
            if not bounding_box:
                logging.warning("   Could not get button position")
                continue
            
            center_x = bounding_box['x'] + bounding_box['width'] / 2
            center_y = bounding_box['y'] + bounding_box['height'] / 2
            
            # Move and press
            logging.info("   Moving mouse to button...")
            page.mouse.move(center_x, center_y, steps=25)
            time.sleep(random.uniform(0.3, 0.6))
            
            logging.info("   Pressing and holding (90s)...")
            page.mouse.down()
            
            hold_duration = 90
            start_time = time.time()
            
            # Monitor for solve during hold
            while time.time() - start_time < hold_duration:
                elapsed = time.time() - start_time
                
                try:
                    if "captcha" not in page.url.lower():
                        page.mouse.up()
                        logging.info(f"   [SUCCESS] CAPTCHA SOLVED after {elapsed:.1f}s!")
                        time.sleep(2)
                        return True
                except:
                    pass
                
                time.sleep(0.5)
            
            page.mouse.up()
            logging.info("   Released mouse button")
            time.sleep(3)
            
            # Final check
            if "captcha" not in page.url.lower():
                logging.info("   [SUCCESS] CAPTCHA SOLVED!")
                return True
            else:
                logging.warning("   CAPTCHA not solved yet")
                
        except Exception as e:
            logging.error(f"   Attempt {attempt + 1} error: {e}")
            if attempt < max_retries - 1:
                time.sleep(5)
    
    logging.error("   [FAILED] CAPTCHA SOLVE FAILED after all attempts")
    return False

def trigger_and_solve_captcha(page: Page):
    """
    CRITICAL FUNCTION: Trigger captcha on a dummy Skyscanner URL and solve it.
    This establishes a valid session BEFORE loading target affiliate URL.
    """
    try:
        logging.info("\n" + "="*60)
        logging.info("STEP 0: CAPTCHA PRE-SOLVE (Session Validation)")
        logging.info("="*60)
        
        # Generate a random flight search URL to trigger captcha
        captcha_trigger_url = generate_random_flight_url()
        
        logging.info(f"\n1. Loading captcha trigger URL...")
        logging.info(f"   URL: {captcha_trigger_url[:80]}...")
        
        try:
            page.goto(captcha_trigger_url, timeout=60000, wait_until="domcontentloaded")
            time.sleep(random.uniform(5, 8))
        except Exception as e:
            logging.warning(f"   Navigation warning: {e}")
        
        # Check if captcha appeared
        current_url = page.url
        logging.info(f"   Current URL: {current_url[:80]}...")
        
        if "captcha" in current_url.lower():
            logging.info("   [SUCCESS] Captcha triggered successfully!")
            
            # Solve the captcha
            if handle_captcha_challenge(page):
                logging.info("\n   [SUCCESS] CAPTCHA SOLVED! Session is now validated.")
                logging.info("   Session is now captcha-free for ~30-60 minutes")
                time.sleep(3)
                return True
            else:
                logging.error("   [FAILED] Failed to solve captcha")
                return False
        else:
            logging.warning("   [WARNING] Captcha did NOT appear on trigger URL")
            logging.info("   This is unusual but proceeding anyway...")
            return True  # Proceed even if no captcha
        
    except Exception as e:
        logging.error(f"Captcha pre-solve error: {e}")
        return False

