def close_popup_safely(page: Page):
    """Close popup"""
    try:
        close_selectors = [
            'button[aria-label="Close"]',
            'button[title="Close"]', 
            'button.BpkCloseButton_bpk-close-button__default__ZDA3N',
            'button.BpkCloseButton_bpk-button__NDQyM',
            'dialog button[type="button"]',
        ]
        
        for selector in close_selectors:
            try:
                close_button = page.locator(selector).first
                if close_button.is_visible(timeout=2000):
                    close_button.click(timeout=3000, force=True, no_wait_after=True)
                    time.sleep(0.5)
                    return True
            except:
                continue
        
        return False
        
    except Exception as e:
        return False

def find_select_button_on_results_page(page: Page):
    """Find Select button on RESULTS page"""
    try:
        logging.info(f"\n[RESULTS PAGE] Finding Select button...")
        
        current_url = page.url
        if not is_results_page(current_url):
            logging.error(f"   ERROR: Not on results page!")
            return None, None
        
        button_found = False
        button_element = None
        
        try:
            flight_cards = page.locator('div[data-testid*="flight"], div[class*="FlightCard"], div[class*="Ticket"]').all()
            logging.info(f"   Found {len(flight_cards)} flight cards")
            
            for idx, card in enumerate(flight_cards):
                try:
                    select_buttons = card.locator('button:has-text("Select"), a:has-text("Select")').all()
                    
                    for btn in select_buttons:
                        if btn.is_visible(timeout=3000):
                            text = btn.inner_text(timeout=2000).strip().lower()
                            
                            if text == 'select':
                                dimensions = btn.evaluate("el => ({ width: el.clientWidth, height: el.clientHeight })")
                                if dimensions['width'] > 50 and dimensions['height'] > 20:
                                    logging.info(f"   [SUCCESS] Valid Select button found in card {idx}")
                                    button_element = btn
                                    button_found = True
                                    break
                    
                    if button_found:
                        break
                except:
                    continue
        except Exception as e:
            logging.warning(f"   Strategy failed: {e}")
        
        if not button_found:
            logging.info("   [FAILED] Select button NOT found")
            return None, None
        
        return page, button_element
        
    except Exception as e:
        logging.error(f"   Error: {e}")
        return None, None

def find_select_button_on_details_page(page: Page):
    """Find BEST Select button on DETAILS page"""
    try:
        logging.info(f"\n[DETAILS PAGE] Finding Select button...")
        
        current_url = page.url
        if not is_details_page(current_url):
            logging.error(f"   ERROR: Not on details page!")
            return None, None
        
        logging.info("   Waiting for AJAX...")
        try:
            page.wait_for_function(
                "() => document.querySelectorAll('.loading, .spinner').length === 0",
                timeout=20000
            )
            time.sleep(3)
        except:
            pass
        
        button_candidates = []
        
        selectors = [
            'div.PricedCta_ctaButton__OTZiN a.BpkButton_bpk-button__NDRjO.bpk-button--primary',
            'div.PricedCta_ctaButton__OTZiN a[data-testid="pricing-item-redirect-button"]',
            'a[data-testid="pricing-item-redirect-button"]',
            'div.PricedCta_ctaButton__OTZiN a',
            'a.BpkButton_bpk-button__NDRjO.bpk-button--primary',
            'a.bpk-button--primary',
        ]
        
        for selector in selectors:
            try:
                buttons = page.locator(selector).all()
                
                for button in buttons:
                    try:
                        if button.is_visible(timeout=5000):
                            text = button.inner_text(timeout=2000).strip().lower()
                            if 'select' in text:
                                href = button.evaluate("el => el.href || ''")
                                has_external_href = href and 'http' in href and 'skyscanner' not in href
                                
                                dimensions = button.evaluate("el => ({ width: el.clientWidth, height: el.clientHeight })")
                                if dimensions['width'] > 0:
                                    priority = 10 if has_external_href else 5
                                    button_candidates.append({
                                        'button': button,
                                        'href': href,
                                        'external': has_external_href,
                                        'priority': priority
                                    })
                    except:
                        continue
            except:
                continue
        
        if not button_candidates:
            logging.info("   [FAILED] No Select buttons found")
            return None, None
        
        button_candidates.sort(key=lambda x: x['priority'], reverse=True)
        best = button_candidates[0]
        logging.info(f"   [SUCCESS] Found button (external: {best['external']})")
        
        return page, best['button']
        
    except Exception as e:
        logging.error(f"   Error: {e}")
        return None, None

def click_select_button(page: Page, page_type="results"):
    """Click Select button"""
    try:
        logging.info(f"\n{'='*60}")
        logging.info(f"CLICKING SELECT BUTTON ON {page_type.upper()} PAGE")
        logging.info(f"{'='*60}")
        
        current_url = page.url
        context = page.context
        initial_page_count = len(context.pages)
        
        page.wait_for_load_state("domcontentloaded", timeout=60000)
        time.sleep(random.uniform(3, 5))
        
        close_popup_safely(page)
        
        # Find button
        if page_type == "results":
            target_frame, button = find_select_button_on_results_page(page)
        else:
            target_frame, button = find_select_button_on_details_page(page)
        
        if not button:
            logging.info(f"   [FAILED] No Select button found!")
            return False, None
        
        # Scroll into view
        try:
            button.scroll_into_view_if_needed(timeout=15000)
            time.sleep(random.uniform(1.5, 2.5))
        except Exception as e:
            logging.warning(f"   Scroll warning: {e}")
        
        # Click button
        logging.info("   Clicking button...")
        click_success = False
        
        for attempt in range(3):
            try:
                button.click(timeout=15000, force=True)
                click_success = True
                logging.info("   [SUCCESS] Click successful")
                break
            except Exception as e:
                if attempt < 2:
                    logging.warning(f"   Retry {attempt + 1}...")
                    time.sleep(2)
        
        if not click_success:
            logging.info("   [FAILED] Click failed!")
            return False, None
        
        # Wait for navigation
        time.sleep(5)
        
        # Check for new tab (details page only)
        active_page = page
        if page_type == "details":
            final_page_count = len(context.pages)
            if final_page_count > initial_page_count:
                active_page = context.pages[-1]
                logging.info(f"   [SUCCESS] New tab opened!")
        
        new_url = active_page.url
        logging.info(f"   Final URL: {new_url[:80]}...")
        
        if page_type == "results":
            if is_details_page(new_url):
                logging.info("   [SUCCESS] Successfully navigated to DETAILS page")
                return True, active_page
            else:
                return False, None
        else:  # details page
            if 'skyscanner.co.in' not in new_url or len(context.pages) > initial_page_count:
                logging.info("   [SUCCESS] Successfully navigated to external site")
                return True, active_page
            else:
                return True, active_page
        
    except Exception as e:
        logging.error(f"   Error: {e}")
        return False, None

def ultimate_human_browsing(page: Page):
    """Main browsing flow with captcha pre-solve"""
    try:
        logging.info("\n" + "="*80)
        logging.info("STARTING ULTIMATE HUMAN BROWSING FLOW")
        logging.info("="*80)
        
        # ============================================================
        # STEP 0: CAPTCHA PRE-SOLVE (CRITICAL!)
        # ============================================================
        captcha_solved = trigger_and_solve_captcha(page)
        
        if not captcha_solved:
            logging.error("[FAILED] Failed to pre-solve captcha. Aborting this profile.")
            return False
        
        logging.info("\n[SUCCESS] Session validated! Proceeding with captcha-free flow...")
        time.sleep(random.uniform(3, 5))
        
        # ============================================================
        # STEP 1: LOAD TARGET AFFILIATE URL (Now captcha-free!)
        # ============================================================
        logging.info(f"\n{'='*60}")
        logging.info(f"STEP 1: Loading Target Affiliate URL")
        logging.info(f"{'='*60}")
        
        for url in TARGET_URLS:
            logging.info(f"\nTarget URL: {url}")
            
            for attempt in range(3):
                try:
                    page.goto(url, timeout=60000, wait_until="networkidle")
                    logging.info("[SUCCESS] Target URL loaded successfully")
                    break
                except Exception as e:
                    if attempt == 2:
                        logging.error(f"[FAILED] Failed to load target URL: {e}")
                        return False
                    time.sleep(3)
            
            time.sleep(random.uniform(6, 10))
            
            # Check if captcha appeared (should NOT happen!)
            if "captcha" in page.url.lower():
                logging.error("[FAILED] UNEXPECTED: Captcha appeared on target URL!")
                logging.error("   This means session validation failed.")
                return False
            
            logging.info("[SUCCESS] No captcha on target URL - session is valid!")
        
        # ============================================================
        # STEP 2: FLIGHT SEARCH (RESULTS PAGE)
        # ============================================================
        logging.info(f"\n{'='*60}")
        logging.info(f"STEP 2: Flight Search (RESULTS PAGE)")
        logging.info(f"{'='*60}")
        
        flight_loaded = False
        
        for flight_attempt in range(3):
            logging.info(f"\nFlight search attempt {flight_attempt + 1}/3")
            
            flight_url = generate_random_flight_url()
            
            try:
                page.goto(flight_url, timeout=60000, wait_until="networkidle")
            except:
                if flight_attempt == 2:
                    break
                continue
            
            time.sleep(random.uniform(8, 12))
            
            current_url = page.url
            
            # Check for unexpected captcha
            if "captcha" in current_url.lower():
                logging.warning("[WARNING] Captcha appeared on flight search")
                if handle_captcha_challenge(page):
                    logging.info("[SUCCESS] Captcha solved again")
                else:
                    if flight_attempt < 2:
                        continue
                    break
            
            if not is_results_page(current_url):
                if flight_attempt < 2:
                    continue
                break
            
            logging.info("[SUCCESS] On RESULTS page")
            
            # Human behavior
            time.sleep(random.uniform(4, 6))
            for _ in range(random.randint(6, 10)):
                action = random.choice(['scroll', 'mouse_move', 'pause'])
                if action == 'scroll':
                    page.evaluate(f"window.scrollBy({{top: {random.randint(100, 250)}, behavior: 'smooth'}});")
                    time.sleep(random.uniform(2, 4))
                elif action == 'mouse_move':
                    page.mouse.move(random.randint(200, 800), random.randint(200, 600), steps=random.randint(15, 25))
                    time.sleep(random.uniform(1.5, 3))
                else:
                    time.sleep(random.uniform(2, 4))
            
            # ============================================================
            # STEP 3: FIRST SELECT BUTTON (Results -> Details)
            # ============================================================
            logging.info(f"\n{'='*60}")
            logging.info(f"STEP 3: First Select Button Click")
            logging.info(f"{'='*60}")
            
            success, new_page = click_select_button(page, "results")
            if success:
                time.sleep(3)
                if new_page:
                    page = new_page
                if is_details_page(page.url):
                    logging.info("[SUCCESS] Moved to DETAILS page")
                    flight_loaded = True
                    break
        
        if not flight_loaded:
            logging.info("\n[FAILED] Failed to reach details page")
            return True
        
        # Verify on details page
        if not is_details_page(page.url):
            logging.error("[FAILED] Not on details page!")
            return True
        
        logging.info("[SUCCESS] Confirmed on DETAILS page")
        
        # Human behavior on details page
        time.sleep(random.uniform(5, 8))
        for _ in range(random.randint(8, 12)):
            action = random.choice(['scroll', 'mouse_move', 'pause'])
            if action == 'scroll':
                page.evaluate(f"window.scrollBy({{top: {random.randint(150, 300)}, behavior: 'smooth'}});")
                time.sleep(random.uniform(2, 4))
            elif action == 'mouse_move':
                page.mouse.move(random.randint(200, 900), random.randint(200, 700), steps=random.randint(15, 30))
                time.sleep(random.uniform(1.5, 3))
            else:
                time.sleep(random.uniform(2, 5))
        
        # ============================================================
        # STEP 4: SECOND SELECT BUTTON (Details -> Booking Site)
        # ============================================================
        logging.info(f"\n{'='*60}")
        logging.info(f"STEP 4: Second Select Button Click")
        logging.info(f"{'='*60}")
        
        success, booking_page = click_select_button(page, "details")
        
        if success:
            logging.info("[SUCCESS] Second Select button clicked successfully")
            
            if booking_page and booking_page != page:
                final_page = booking_page
            else:
                final_page = page
            
            # Final human behavior on booking site
            time.sleep(3)
            
            human_time = random.uniform(*HUMAN_BEHAVIOR_TIME)
            logging.info(f"\nFinal page human behavior for {human_time:.1f}s")
            logging.info(f"Final page URL: {final_page.url[:80]}")
            
            start_time = time.time()
            while time.time() - start_time < human_time:
                try:
                    action = random.choice(['scroll', 'mouse_move', 'pause'])
                    
                    if action == 'scroll':
                        final_page.evaluate(f"window.scrollBy({{top: {random.randint(50, 150)}, behavior: 'smooth'}});")
                    elif action == 'mouse_move':
                        final_page.mouse.move(random.randint(100, 800), random.randint(100, 600))
                    else:
                        time.sleep(random.uniform(1, 3))
                    
                    time.sleep(random.uniform(1, 2))
                except Exception as e:
                    logging.warning(f"   Human behavior warning: {str(e)[:50]}")
                    break
            
            logging.info("[SUCCESS] Human behavior completed on booking page")
        else:
            logging.info("[FAILED] Failed second click")
        
        logging.info("\n" + "="*80)
        logging.info("[SUCCESS] HUMAN BEHAVIOR FLOW COMPLETE!")
        logging.info("="*80)
        return True
        
    except Exception as e:
        logging.error(f"Human browsing error: {e}")
        logging.error(traceback.format_exc())
        return False

def create_ultimate_stealth_profile(profile_name, profile_num):
    """Create profile with Geonode rotating proxy"""
    global current_token_idx
    while current_token_idx < len(tokens):
        TOKEN = tokens[current_token_idx]
        try:
            gl = GoLogin({"token": TOKEN})
            logging.info(f"Creating stealth profile: {profile_name}")
            
            proxy_config = get_geonode_rotating_proxy()
            
            profile = gl.createProfileRandomFingerprint({
                "os": random.choice(["win", "mac"]),
                "name": profile_name,
                "webgl": {
                    "vendor": random.choice(["Intel Inc.", "NVIDIA Corporation", "AMD"]),
                    "renderer": random.choice(["Intel Iris OpenGL Engine", "GeForce GTX 1650/PCIe/SSE2"])
                },
                "audioContext": {
                    "enable": True,
                    "noise": random.uniform(0.0001, 0.0005)
                }
            })
            
            if not profile or 'id' not in profile:
                raise Exception("Profile creation failed")
                
            profile_id = profile['id']
            logging.info(f"Profile created: {profile_id}")
            
            # Apply Geonode proxy
            try:
                proxy_data = {
                    "mode": proxy_config['type'],
                    "host": proxy_config['host'],
                    "port": int(proxy_config['port']),
                    "username": proxy_config.get('username', ''),
                    "password": proxy_config.get('password', '')
                }
                gl.changeProfileProxy(profile_id, proxy_data)
                logging.info(f"[SUCCESS] Geonode proxy configured for Profile #{profile_num}")
                logging.info(f"  Proxy: {proxy_config['type']}://{proxy_config['host']}:{proxy_config['port']}")
            except Exception as e:
                logging.warning(f"Proxy setup warning: {e}")
            
            return profile_id
            
        except Exception as e:
            logging.error(f"Error with token {current_token_idx}: {e}")
            current_token_idx += 1
            if current_token_idx >= len(tokens):
                logging.error("All tokens exhausted")
                return None
            logging.info(f"Switching to next token {current_token_idx}")
    
    return None

def start_maximum_stealth_browser(profile_id):
    """Start browser with stealth"""
    try:
        gl = GoLogin({
            "token": tokens[current_token_idx],
            "profile_id": profile_id
        })
        logging.info(f"Starting browser for: {profile_id}")
        debugger_address = gl.start()
        
        time.sleep(random.uniform(3, 5))
        
        pw = sync_playwright().start()
        cdp_url = f"http://{debugger_address}"
        browser = pw.chromium.connect_over_cdp(cdp_url)
        context = browser.contexts[0]
        if context.pages:
            page = context.pages[0]
        else:
            page = context.new_page()
        
        context.set_extra_http_headers({
            "DNT": "1",
            "Accept-Language": "en-US,en;q=0.9,hi;q=0.8",
        })
        
        inject_ultimate_stealth(page)
        
        return gl, pw, browser, page
        
    except Exception as e:
        logging.error(f"Browser start error: {e}")
        return None, None, None, None

def cleanup_browser(gl: GoLogin, pw: Playwright, browser: Browser):
    """Cleanup browser resources"""
    try:
        if browser:
            browser.close()
        time.sleep(1)
        if gl:
            gl.stop()
        if pw:
            pw.stop()
        logging.info("Browser session terminated")
    except Exception as e:
        logging.warning(f"Cleanup warning: {e}")

